const listRunnerTokens = `-- name: ListRunnerTokens :many
SELECT id, prefix, last_used_time, create_time FROM runner_tokens
WHERE org_id = $1 AND data_plane_id = $2
ORDER BY create_time, id
`

type ListRunnerTokensParams struct {
	OrgID       uuid.UUID
	DataPlaneID string
}

type ListRunnerTokensRow struct {
	ID           uuid.UUID
	Prefix       string
	LastUsedTime *time.Time
	CreateTime   time.Time
}

func (q *Queries) ListRunnerTokens(ctx context.Context, arg ListRunnerTokensParams) ([]ListRunnerTokensRow, error) {
	rows, err := q.db.Query(ctx, listRunnerTokens, arg.OrgID, arg.DataPlaneID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRunnerTokensRow
	for rows.Next() {
		var i ListRunnerTokensRow
		if err := rows.Scan(
			&i.ID,
			&i.Prefix,
			&i.LastUsedTime,
			&i.CreateTime,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockOrgOwners = `-- name: LockOrgOwners :many
SELECT p.id FROM role_bindings b JOIN principals p ON p.org_id = b.org_id AND p.id = b.principal_id
WHERE b.org_id = $1 AND b.role = 'owner' AND b.workspace_id IS NULL AND NOT p.disabled
FOR UPDATE
`

// The enabled principals bound as owner on the org, locked, so changes that
// could leave none are serialized.
func (q *Queries) LockOrgOwners(ctx context.Context, orgID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, lockOrgOwners, orgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const pipelineOnDataPlane = `-- name: PipelineOnDataPlane :one
SELECT
    EXISTS (SELECT 1 FROM pipelines p WHERE p.org_id = $1 AND p.id = $2) AS found,
    EXISTS (
        SELECT 1 FROM pipeline_versions v
        WHERE v.org_id = $1 AND v.pipeline_id = $2 AND v.data_plane_id = $3
    ) AS on_data_plane
`

type PipelineOnDataPlaneParams struct {
	OrgID       uuid.UUID
	PipelineID  uuid.UUID
	DataPlaneID string
}

type PipelineOnDataPlaneRow struct {
	Found       bool
	OnDataPlane bool
}

// Whether the pipeline exists, and whether a version of it runs on the data
// plane.
func (q *Queries) PipelineOnDataPlane(ctx context.Context, arg PipelineOnDataPlaneParams) (PipelineOnDataPlaneRow, error) {
	row := q.db.QueryRow(ctx, pipelineOnDataPlane, arg.OrgID, arg.PipelineID, arg.DataPlaneID)
	var i PipelineOnDataPlaneRow
	err := row.Scan(&i.Found, &i.OnDataPlane)
	return i, err
}

const recordSignInFailure = `-- name: RecordSignInFailure :exec
UPDATE passwords SET
    failures = CASE WHEN locked_until <= now() THEN 1 ELSE failures + 1 END,
    locked_until = CASE
        WHEN locked_until > now() THEN locked_until
        WHEN (CASE WHEN locked_until <= now() THEN 1 ELSE failures + 1 END) >= $1::integer
            THEN now() + make_interval(secs => $2::integer)
    END
WHERE org_id = $3 AND principal_id = $4
`

type RecordSignInFailureParams struct {
	MaxFailures int32
	LockSeconds int32
	OrgID       uuid.UUID
	PrincipalID uuid.UUID
}

// Counts a failed sign-in, and locks the password for lock_seconds once
// max_failures fail in a row. The count starts again once a lock is over.
func (q *Queries) RecordSignInFailure(ctx context.Context, arg RecordSignInFailureParams) error {
	_, err := q.db.Exec(ctx, recordSignInFailure,
		arg.MaxFailures,
		arg.LockSeconds,
		arg.OrgID,
		arg.PrincipalID,
	)
	return err
}

const setPassword = `-- name: SetPassword :exec
INSERT INTO passwords (org_id, principal_id, hash)
VALUES ($1, $2, $3)
ON CONFLICT (org_id, principal_id) DO UPDATE SET hash = excluded.hash, failures = 0, locked_until = NULL, update_time = now()
`

type SetPasswordParams struct {
	OrgID       uuid.UUID
	PrincipalID uuid.UUID
	Hash        string
}

// Sets a password and clears its failures and lock.
func (q *Queries) SetPassword(ctx context.Context, arg SetPasswordParams) error {
	_, err := q.db.Exec(ctx, setPassword, arg.OrgID, arg.PrincipalID, arg.Hash)
	return err
}

